(()=>{const root=document.querySelector('[data-structured-bundle]');if(!root)return;const toast=(m,b=false)=>{const n=document.getElementById('homebrewToast');if(!n)return;n.textContent=m;n.classList.toggle('bad',b);n.classList.add('show');clearTimeout(n._t);n._t=setTimeout(()=>n.classList.remove('show'),3500)};document.querySelector('[data-bundle-foundry]')?.addEventListener('click',async e=>{e.currentTarget.disabled=true;try{const r=await fetch(`/api/v61/foundry/content/${root.dataset.structuredBundle}/push`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({target_type:'world'})});const out=await r.json().catch(()=>({}));if(!r.ok)throw Error(out.detail||'Could not queue Foundry import.');toast(`Foundry import queued · command #${out.command?.id||'—'}`)}catch(err){toast(err.message,true)}finally{e.currentTarget.disabled=false}})})();
